CREATE     PROCEDURE [synapse_fo].[usp_Insert_LEDGERJOURNALTABLE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:52
	Description: Insert stored procedure for LEDGERJOURNALTABLE from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[LEDGERJOURNALTABLE]
	(
		[APPROVER],
		[ASSETLEASEPROCESSID],
		[ASSETTRANSFERTYPE_LT],
		[BANKACCOUNTID],
		[BANKREMITTANCETYPE],
		[BANKTRANSSUMMARIZATIONCRITERIA],
		[BANKTRANSSUMMARIZATIONENABLED],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CURRENCYCODE],
		[CURRENTOPERATIONSTAX],
		[CUSTVENDNEGINSTPROTESTPROCESS],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEFAULTDIMENSION],
		[DELAYTAXCALCULATION],
		[DETAILSUMMARYPOSTING],
		[DOCUMENTNUM],
		[ENDBALANCE],
		[EUROTRIANGULATION],
		[EXCHRATE],
		[EXCHRATESECONDARY],
		--[FileName],
		[FINTAG],
		[FIXEDEXCHRATE],
		[FIXEDOFFSETACCOUNT],
		[GROUPBLOCKID],
		[INTEGRATIONKEY],
		[INUSEBY],
