		[LastProcessedChange_DateTime],
		[LEDGERJOURNALINCLTAX],
		[LINESLIMITBEFOREDISTRIBUTION],
		[LOG],
		--[LSN],
		[MODIFIEDBY],
		[NAME],
		[NUMBERSEQUENCETABLE],
		[NUMOFLINES],
		[OFFSETACCOUNTTYPE],
		[OFFSETLEDGERDIMENSION],
		[ORIGINALCOMPANY],
		[ORIGINALJOURNALNUM],
		[OVERRIDESALESTAX],
		[PARENTJOURNALNUM],
		[PARTITION],
		[PAYMENTSGENERATED_IT],
		[POSTED],
		[POSTEDDATETIME],
		--[POSTEDDATETIMETZID],
		[PROTESTSETTLEDBILL],
		[RECID],
		[RECVERSION],
		[REJECTEDBY],
		[REMOVELINEAFTERPOSTING],
		[REPORTEDASREADYBY],
		[REPORTINGCURRENCYEXCHRATE],
		[REPORTINGCURRENCYEXCHRATESECONDARY],
		[REPORTINGCURRENCYFIXEDEXCHRATE],
		[RETAILSTATEMENTID],
		[REVERSEDATE],
		[REVERSEENTRY],
		[REVRECREALLOCATIONID],
		[SESSIONID],
		[SESSIONLOGINDATETIME],
		--[SESSIONLOGINDATETIMETZID],
		[SIMULATIONPOSTED_IT],
		--[SKS_EFT_AUTOCREATE],
		--[SKS_EFT_JOURNALSTATE],
		--[SKS_EFTAP_ACCEPTPAYMREQ],
		--[SKS_EFTAP_CREATEDBYPAYMREQ],
		--[SKS_EFTAP_INTERCOMPSOURCEDATAAREAID],
		--[SKS_EFTAP_INTERCOMPSOURCEJOURNALNUM],
		--[SKS_EFTAP_ISCREATEDBYREQJOURNAL],
		--[SKS_EFTAP_ISIHBJOURNAL],
		--[SKS_EFTAP_ISPAYMENTCALENDARJOURNAL],
		--[SKS_EFTAP_ISPAYMREQJOURNAL],
		--[SKS_EFTAP_PAYGROUP],
		--[SKS_EFTAP_PAYMENTCOMPANY],
		--[SKS_EFTAP_PAYMENTSUBMITDATETIME],
		--[SKS_EFTAP_PAYMENTSUBMITDATETIMETZID],
		--[SKS_EFTAP_PAYMENTSUBMITUSER],
