		--[SKS_EPY_BATCHID],
		--[SKS_EPY_EPAYCREATED],
		--[SKS_EPY_JOURNALDATE],
		--[SKS_PL_ISPAYLINK],
		--[SysRowId],
		[SYSTEMBLOCKED],
		[TAXOBLIGATIONCOMPANY],
		[USERBLOCKID],
		[VOUCHERALLOCATEDATPOSTING],
		[WORKFLOWAPPROVALSTATUS]
	)
	SELECT 
		stg.[APPROVER],
		stg.[ASSETLEASEPROCESSID],
		stg.[ASSETTRANSFERTYPE_LT],
		stg.[BANKACCOUNTID],
		stg.[BANKREMITTANCETYPE],
		stg.[BANKTRANSSUMMARIZATIONCRITERIA],
		stg.[BANKTRANSSUMMARIZATIONENABLED],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CURRENCYCODE],
		stg.[CURRENTOPERATIONSTAX],
		stg.[CUSTVENDNEGINSTPROTESTPROCESS],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEFAULTDIMENSION],
		stg.[DELAYTAXCALCULATION],
		stg.[DETAILSUMMARYPOSTING],
		stg.[DOCUMENTNUM],
		stg.[ENDBALANCE],
		stg.[EUROTRIANGULATION],
		stg.[EXCHRATE],
		stg.[EXCHRATESECONDARY],
		--stg.--[FileName],
		stg.[FINTAG],
		stg.[FIXEDEXCHRATE],
		stg.[FIXEDOFFSETACCOUNT],
		stg.[GROUPBLOCKID],
		stg.[INTEGRATIONKEY],
		stg.[INUSEBY],
		stg.[ISADJUSTMENTJOURNAL],
		stg.[ISLEDGERDIMENSIONNAMEUPDATED],
		stg.[JOURNALBALANCE],
		stg.[JOURNALNAME],
		stg.[JOURNALNUM],
		stg.[JOURNALTOTALCREDIT],
		stg.[JOURNALTOTALCREDITREPORTINGCURRENCY],
		stg.[JOURNALTOTALDEBIT],
		stg.[JOURNALTOTALDEBITREPORTINGCURRENCY],
		stg.[JOURNALTOTALOFFSETBALANCE],
		stg.[JOURNALTYPE],
		stg.[LastProcessedChange_DateTime],
		stg.[LEDGERJOURNALINCLTAX],
		stg.[LINESLIMITBEFOREDISTRIBUTION],
		stg.[LOG],
		--stg.--[LSN],
		stg.[MODIFIEDBY],
		stg.[NAME],
		stg.[NUMBERSEQUENCETABLE],
		stg.[NUMOFLINES],
		stg.[OFFSETACCOUNTTYPE],
		stg.[OFFSETLEDGERDIMENSION],
		stg.[ORIGINALCOMPANY],
		stg.[ORIGINALJOURNALNUM],
		stg.[OVERRIDESALESTAX],
		stg.[PARENTJOURNALNUM],
		stg.[PARTITION],
		stg.[PAYMENTSGENERATED_IT],
		stg.[POSTED],
		stg.[POSTEDDATETIME],
		--stg.[POSTEDDATETIMETZID],
		stg.[PROTESTSETTLEDBILL],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REJECTEDBY],
		stg.[REMOVELINEAFTERPOSTING],
		stg.[REPORTEDASREADYBY],
		stg.[REPORTINGCURRENCYEXCHRATE],
		stg.[REPORTINGCURRENCYEXCHRATESECONDARY],
		stg.[REPORTINGCURRENCYFIXEDEXCHRATE],
		stg.[RETAILSTATEMENTID],
		stg.[REVERSEDATE],
		stg.[REVERSEENTRY],
		stg.[REVRECREALLOCATIONID],
		stg.[SESSIONID],
		stg.[SESSIONLOGINDATETIME],
		--stg.[SESSIONLOGINDATETIMETZID],
		stg.[SIMULATIONPOSTED_IT],
		--stg.[SKS_EFT_AUTOCREATE],
		--stg.[SKS_EFT_JOURNALSTATE],
		--stg.[SKS_EFTAP_ACCEPTPAYMREQ],
		--stg.[SKS_EFTAP_CREATEDBYPAYMREQ],
		--stg.[SKS_EFTAP_INTERCOMPSOURCEDATAAREAID],
		--stg.[SKS_EFTAP_INTERCOMPSOURCEJOURNALNUM],
		--stg.[SKS_EFTAP_ISCREATEDBYREQJOURNAL],
		--stg.[SKS_EFTAP_ISIHBJOURNAL],
		--stg.[SKS_EFTAP_ISPAYMENTCALENDARJOURNAL],
		--stg.[SKS_EFTAP_ISPAYMREQJOURNAL],
		--stg.[SKS_EFTAP_PAYGROUP],
		--stg.[SKS_EFTAP_PAYMENTCOMPANY],
		--stg.[SKS_EFTAP_PAYMENTSUBMITDATETIME],
		--stg.[SKS_EFTAP_PAYMENTSUBMITDATETIMETZID],
		--stg.[SKS_EFTAP_PAYMENTSUBMITUSER],
		--stg.[SKS_EFTAP_PAYMJOURNAME],
		--stg.[SKS_EPY_BATCHID],
		--stg.[SKS_EPY_EPAYCREATED],
		--stg.[SKS_EPY_JOURNALDATE],
		--stg.[SKS_PL_ISPAYLINK],
		--stg.--[SysRowId],
		stg.[SYSTEMBLOCKED],
		stg.[TAXOBLIGATIONCOMPANY],
		stg.[USERBLOCKID],
		stg.[VOUCHERALLOCATEDATPOSTING],
		stg.[WORKFLOWAPPROVALSTATUS]	
	FROM [staging_fo].[LEDGERJOURNALTABLE] stg
		LEFT JOIN [synapse_fo].[LEDGERJOURNALTABLE] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[JournalNum] = tgt.[JournalNum] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
	WHERE tgt.[RECID] IS NULL
END
